    """Render as TOML string."""
    s = ""
    for k, v in self._body:
        if k is not None:
            if isinstance(v, Table):
                if (
                    s.strip(" ")
                    and not s.strip(" ").endswith("\n")
                    and "\n" not in v.trivia.indent
